INSERT INTO fertilizer_types (id,name,description,est_days_to_finish) VALUES (4,'Hot Composting','An actively managed outdoor pile. Balance greens, browns, air and moisture, then allow the compost to cure.',120) ON CONFLICT (id) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (4,1,'Remove packaging. Use chopped plant scraps with dry leaves or plain shredded cardboard.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (4,2,'Keep meat, dairy, oil, pet waste and treated materials out of this household pile.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (4,3,'Build a substantial pile in a ventilated bin; small piles may not retain heat.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (4,4,'Mix greens and browns, keeping the pile damp with space for air.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (4,5,'Check the centre with a compost thermometer; a photo cannot measure temperature.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (4,6,'Turn and adjust moisture as needed; add dry browns if the pile becomes soggy.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (4,7,'After active heating stops, allow curing. Use only when stable, crumbly and earthy.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_maintenance_guides (fertilizer_type_id,check_cadence,optimal_temp,moisture_range) VALUES (4,'Check heat and moisture regularly; turn as needed','Measure with a compost thermometer; photos do not show heat','Damp, with airflow; add browns if waterlogged') ON CONFLICT (fertilizer_type_id) DO NOTHING;
INSERT INTO waste_fertilizer_matches (waste_type_id,fertilizer_type_id) SELECT id,4 FROM waste_types WHERE id=1 AND is_supported ON CONFLICT (waste_type_id,fertilizer_type_id) DO NOTHING;
