INSERT INTO fertilizer_suitable_plants (fertilizer_type_id,plant_id,is_recommended,notes) SELECT 4,id,(id<=18),CASE WHEN id<=18 THEN 'Use only mature compost; check the plant, soil and drainage needs.' ELSE 'Use specialist growing-medium guidance.' END FROM plants WHERE id BETWEEN 1 AND 20 ON CONFLICT (fertilizer_type_id,plant_id) DO NOTHING;
INSERT INTO fertilizer_types (id,name,description,est_days_to_finish) VALUES (5,'Cold Composting','A slower outdoor method with less turning. Add suitable plant scraps and browns, cover food and give the mix time.',270) ON CONFLICT (id) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (5,1,'Collect fruit and vegetable scraps and a separate supply of dry plant material.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (5,2,'Remove contaminants; leave meat, dairy, grease and diseased plants out.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (5,3,'Choose a draining, ventilated outdoor bin; add materials gradually.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (5,4,'Cover food additions with browns to discourage pests; keep air spaces in the mix.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (5,5,'Moisten dry material gently. Mix if compacted or smelly; avoid waterlogging.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (5,6,'Let the material decompose slowly, with occasional checks and less frequent turning.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (5,7,'Harvest only the fully decomposed, earthy portion. Leave recognisable scraps to continue breaking down.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_maintenance_guides (fertilizer_type_id,check_cadence,optimal_temp,moisture_range) VALUES (5,'Check occasionally and after heavy rain or dry weather','No sustained high-heat target; decomposition is slower','Moist and draining; avoid compacted, soggy layers') ON CONFLICT (fertilizer_type_id) DO NOTHING;
INSERT INTO waste_fertilizer_matches (waste_type_id,fertilizer_type_id) SELECT id,5 FROM waste_types WHERE id=1 AND is_supported ON CONFLICT (waste_type_id,fertilizer_type_id) DO NOTHING;
