INSERT INTO fertilizer_types (id,name,description,est_days_to_finish) VALUES (6,'Bokashi Composting','Ferment food with Bokashi bran in an airtight bucket, then finish breaking it down in soil or a compost system. Fermented scraps are not finished compost.',42) ON CONFLICT (id) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (6,1,'Use a Bokashi bucket with a tap and inoculated bran; keep it shaded.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (6,2,'Chop food and remove packaging. SoilSync currently matches plant-based scraps; exclude excess liquids and oil.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (6,3,'Add food in shallow layers with bran, following the kit''s quantities.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (6,4,'Press out air and close the airtight lid after each addition. Do not stir to aerate.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (6,5,'Drain accumulated liquid using the tap every few days; follow the kit''s disposal instructions.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (6,6,'Once full, leave sealed for around 2 weeks. The fermented contents are pre-compost.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_recipe_steps (fertilizer_type_id,step_number,instruction) VALUES (6,7,'Bury in an unplanted area or add to a compost system for further breakdown. Keep away from roots and wait at least 2 weeks before planting; allow longer if scraps remain.') ON CONFLICT (fertilizer_type_id,step_number) DO NOTHING;
INSERT INTO fertilizer_maintenance_guides (fertilizer_type_id,check_cadence,optimal_temp,moisture_range) VALUES (6,'Keep sealed; drain the tap every few days','Keep shaded; no hot-pile target or aerating turns','Avoid excess liquid; drain without leaving the lid open') ON CONFLICT (fertilizer_type_id) DO NOTHING;
INSERT INTO waste_fertilizer_matches (waste_type_id,fertilizer_type_id) SELECT id,6 FROM waste_types WHERE id=1 AND is_supported ON CONFLICT (waste_type_id,fertilizer_type_id) DO NOTHING;
