INSERT INTO fertilizer_suitable_plants (fertilizer_type_id,plant_id,is_recommended,notes) SELECT 6,id,(id<=18),CASE WHEN id<=18 THEN 'Use only fully finished compost; check the plant and soil needs. Bokashi pre-compost must finish breaking down away from roots.' ELSE 'Use specialist growing-medium guidance.' END FROM plants WHERE id BETWEEN 1 AND 20 ON CONFLICT (fertilizer_type_id,plant_id) DO NOTHING;
