-- Approved methods: new IDs preserve all existing batch/scan references.
-- Apply once through Alembic 0004, or once in pgAdmin after migration 0003.
BEGIN;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM fertilizer_types WHERE id=4 AND name<>'Hot Composting') THEN RAISE EXCEPTION 'Recipe ID 4 already belongs to a different recipe'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM fertilizer_types WHERE id=5 AND name<>'Cold Composting') THEN RAISE EXCEPTION 'Recipe ID 5 already belongs to a different recipe'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM fertilizer_types WHERE id=6 AND name<>'Bokashi Composting') THEN RAISE EXCEPTION 'Recipe ID 6 already belongs to a different recipe'; END IF; END $$;
SELECT setval(pg_get_serial_sequence('fertilizer_types','id'), GREATEST((SELECT MAX(id) FROM fertilizer_types), nextval(pg_get_serial_sequence('fertilizer_types','id')), 6), true);
COMMIT;
